function countsAllDistinct(nums: number[]): boolean {
  const a = [...nums].sort((x, y) => x - y);
  const runs: number[] = [];
  let len = 1;
  for (let i = 1; i <= a.length; i++) {
    if (i < a.length && a[i] === a[i - 1]) len++;
    else { runs.push(len); len = 1; }
  }
  runs.sort((x, y) => x - y);
  for (let i = 1; i < runs.length; i++) if (runs[i] === runs[i - 1]) return false;
  return true;
}

