class Solution:
    def countsAllDistinct(self, nums: List[int]) -> bool:
        a = sorted(nums)
        runs, length = [], 1
        for i in range(1, len(a) + 1):
            if i < len(a) and a[i] == a[i - 1]:
                length += 1
            else:
                runs.append(length)
                length = 1
        runs.sort()
        return all(runs[i] != runs[i - 1] for i in range(1, len(runs)))

